            <div style={{ marginTop: '12px', display: 'flex', flexDirection: 'column', gap: '12px' }}>{v.sgBuild.map((st, stI) => (<React.Fragment key={stI}><div style={{ display: 'flex', gap: '12px' }}><span style={{ flexShrink: 0, width: '26px', height: '26px', borderRadius: '8px', background: 'rgba(14,165,233,0.12)', color: '#0284c7', fontSize: '11px', fontWeight: 800, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{st.n}</span><span style={{ fontSize: '14px', lineHeight: 1.65, color: '#374151' }}>{st.t}</span></div></React.Fragment>))}</div>
